<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/helpers.php';require_once __DIR__.'/../lib/fulfilment.php';require_once __DIR__.'/../lib/notifications.php';
send_cors_headers();$context=require_vendor(true);$vendorId=$context['vendor']['id'];$db=get_db();$method=$_SERVER['REQUEST_METHOD']??'GET';
if($method==='GET'){$id=trim((string)($_GET['id']??''));if($id!==''){$group=vendor_group($id,$vendorId);$items=$db->prepare('SELECT * FROM order_items WHERE vendor_group_id=:group');$items->execute(['group'=>$id]);$packages=$db->prepare('SELECT * FROM shipment_packages WHERE vendor_group_id=:group ORDER BY created_at');$packages->execute(['group'=>$id]);$group['address']=json_decode((string)$group['address_snapshot_json'],true);unset($group['address_snapshot_json']);$group['items']=$items->fetchAll();$group['packages']=$packages->fetchAll();json_response(200,['success'=>true,'order'=>$group]);}$status=trim((string)($_GET['status']??''));$params=['vendor'=>$vendorId];$where='g.vendor_id=:vendor';if($status!==''){$where.=' AND g.status=:status';$params['status']=$status;}$stmt=$db->prepare("SELECT g.id,g.group_number,g.status,g.subtotal,g.shipping_amount,g.tax_amount,g.total_amount,g.dispatch_due_at,g.created_at,o.order_number,o.payment_status,COUNT(oi.id) item_count,SUM(oi.quantity) unit_count FROM vendor_order_groups g JOIN orders o ON o.id=g.order_id JOIN order_items oi ON oi.vendor_group_id=g.id WHERE {$where} GROUP BY g.id ORDER BY g.created_at DESC LIMIT 200");$stmt->execute($params);json_response(200,['success'=>true,'orders'=>$stmt->fetchAll()]);}
if($method==='POST'){$body=get_json_body();$id=trim((string)($body['group_id']??''));$next=trim((string)($body['status']??''));$reason=trim((string)($body['reason']??''));$allowed=['accepted','rejected','processing','quality_check','packing','ready_to_dispatch','cancelled'];if(!in_array($next,$allowed,true))json_response(422,['success'=>false,'message'=>'Unsupported order status. Use the package endpoint for shipping milestones.']);if(in_array($next,['rejected','cancelled'],true)&&mb_strlen($reason)<10)json_response(422,['success'=>false,'message'=>'A reason of at least 10 characters is required.']);$db->beginTransaction();try{$group=vendor_group($id,$vendorId,true);assert_transition($group['status'],$next,group_transition_map());$db->prepare('UPDATE vendor_order_groups SET status=:new_status,accepted_at=IF(:accepted_status="accepted",UTC_TIMESTAMP(),accepted_at),updated_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['new_status'=>$next,'accepted_status'=>$next,'id'=>$id]);$db->prepare('UPDATE order_items SET status=:item_status WHERE vendor_group_id=:id AND status NOT IN ("cancelled","delivered","returned")')->execute(['item_status'=>$next,'id'=>$id]);record_status_change('vendor_order_group',$id,$group['status'],$next,$reason?:null);create_notification('customer',$group['user_id'],'order_status','Order status updated',"Order {$group['order_number']} is now ".str_replace('_',' ',$next).'.','../tracking.php?order_id='.$group['order_id'],['group_id'=>$id]);audit_event('vendor.order_status_changed','vendor_order_group',$id,['from'=>$group['status'],'to'=>$next,'reason'=>$reason]);$db->commit();json_response(200,['success'=>true,'message'=>'Order status updated.','status'=>$next]);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}
json_response(405,['success'=>false,'message'=>'Method not allowed.']);
